          '**Weave** — 隶属 Weights & Biases。免费档提供不限数量的 Weave 席位和每月 1 GB 数据摄入。Pro 每月 60 美元起、含 1.5 GB，但资格被明确限定为「early-stage teams fewer than 50 employees」；更大的组织必须转入 Enterprise。额外摄入为每 MB 0.10 美元。',
