          '**OpenAI 于 2026 年 3 月 9 日宣布收购 Promptfoo**，并公开表示：「Promptfoo will remain open source under the current license, and we will continue to service and support current customers。」该仓库目前仍为 MIT 许可，并在本页核实当天有过更新。',
